<template>
  <div class="mainQuestionContainer bg-secondary">
    <h2 class="text-2xl font-semibold mb-2">{{ $t(langKey) }}</h2>

    <!-- Affichage des types -->
    <div class="w-full">
        <input
            v-if="type === 'text' || type === 'number'"
            v-model="valueLocal"
            :type="type"
            :min="type === 'number' ? '0' : undefined"
            :step="type === 'number' ? '0.1' : undefined"
            class="inputAnswer"
            :placeholder="type === 'number' ? 'Entrez un nombre positif' : 'Entrez votre réponse'"
            @input="validateNumberInput"
        />

        <!-- Choix d'options (boutons cliquables) -->
        <div v-else-if="type === 'checkbox' || type === 'radio'" class="optionsContainer">
            <div
                v-for="(opt, i) in options"
                :key="i"
                :class="{
                    'option bg-tertiary borderAccent': multipleChoice ? valueLocal.includes(opt.option) : valueLocal === opt.option,
                    'option bg-tertiary': multipleChoice ? !valueLocal.includes(opt.option) : valueLocal !== opt.option
                }"
                @click="selectOption(opt.option)"
            >
                <span class="option-text">{{ $t(opt.option) }}</span>
            </div>
        </div>
    </div>

    <!-- Message d'erreur IMC -->
    <div v-if="showBMIError" class="error-message bmi-warning">
      <p class="warning-title">⚠️ Attention</p>
      <p class="warning-text">Votre IMC est inférieur à 15 ({{ calculatedBMI.toFixed(1) }}). Pour votre sécurité, nous vous recommandons de consulter un professionnel de santé.</p>
    </div>

    <!-- Navigation -->
    <div class="mt-5 actionContainer">
      <button 
        v-if="question > 1" 
        @click="previousStep" 
        type="button"
        class="previousButton button-base"
      >
        Retour
      </button>
      <button 
        v-if="(multipleChoice && type !== 'text' && type !== 'number') || type === 'number' || type === 'text'" 
        @click="submit" 
        type="button"
        :disabled="showBMIError"
        :class="showBMIError ? 'nextButton nextButton-disabled' : 'nextButton bg-accent'"
        class="button-base"
      >
        Suivant
      </button>
    </div>
  </div>

  <v-snackbar v-model="showError" color="error" top right :timeout="3000">
    {{ errorMessage }}
  </v-snackbar>
</template>

<script>
export default {
    name: 'RegisterQuestionsBlock',
    props: {
        langKey: String,
        question: [String, Number],
        options: Array,
        type: String,
        multipleChoice: Boolean,
        value: [String, Number, Array],
    },
    data() {
        return {
            valueLocal: this.multipleChoice ? [] : '',
            errorMessage: '',
            showError: false,
            showBMIError: false,
            calculatedBMI: 0,
        };
    },
    computed: {
        showHelperText() {
            return this.type === 'select';
        }
    },
    watch: {
        // Reset valueLocal quand on change de question
        langKey(newKey, oldKey) {
            if (newKey !== oldKey) {
                this.resetValue();
            }
        },
        value(newVal) {
            if (newVal !== undefined && newVal !== null) {
                this.valueLocal = this.multipleChoice ? (newVal || []) : (newVal || '');
            }
        },
    },
    mounted() {
        this.resetValue();
    },
    methods: {
        resetValue() {
            // Initialise avec la valeur existante ou une valeur vide
            if (this.value !== undefined && this.value !== null) {
                this.valueLocal = this.multipleChoice ? (this.value || []) : (this.value || '');
            } else {
                this.valueLocal = this.multipleChoice ? [] : '';
            }
            this.showBMIError = false;
        },
        validateNumberInput(event) {
            // Empêche les valeurs négatives
            if (this.type === 'number') {
                const value = parseFloat(event.target.value);
                if (value < 0) {
                    this.valueLocal = '';
                    event.target.value = '';
                }
            }
        },
        checkBMI() {
            // Vérifie l'IMC si on a le poids et la taille
            const responses = this.$parent.responses || {};
            const weight = parseFloat(responses.actualWeight);
            const heightCm = parseFloat(responses.actualSize);
            
            if (weight && heightCm && heightCm > 0) {
                const heightM = heightCm / 100;
                const bmi = weight / (heightM * heightM);
                
                if (bmi < 15) {
                    this.showBMIError = true;
                    this.calculatedBMI = bmi;
                    return false;
                }
            }
            
            this.showBMIError = false;
            return true;
        },
        submit() {
            // Validation de base
            if (!this.valueLocal || (Array.isArray(this.valueLocal) && this.valueLocal.length === 0)) {
                this.errorMessage = 'Veuillez répondre à la question';
                this.showError = true;
                return;
            }

            // Validation pour les nombres
            if (this.type === 'number') {
                const numValue = parseFloat(this.valueLocal);
                if (isNaN(numValue) || numValue < 0) {
                    this.errorMessage = 'Veuillez entrer un nombre valide et positif';
                    this.showError = true;
                    return;
                }

                // Validation spécifique pour le poids
                if (this.langKey === 'actualWeight' && (numValue < 20 || numValue > 300)) {
                    this.errorMessage = 'Veuillez entrer un poids réaliste (entre 20 et 300 kg)';
                    this.showError = true;
                    return;
                }

                // Validation spécifique pour la taille
                if (this.langKey === 'actualSize' && (numValue < 50 || numValue > 250)) {
                    this.errorMessage = 'Veuillez entrer une taille réaliste (entre 50 et 250 cm)';
                    this.showError = true;
                    return;
                }

                // Validation spécifique pour l'âge
                if (this.langKey === 'age' && (numValue < 10 || numValue > 120)) {
                    this.errorMessage = 'Veuillez entrer un âge réaliste (entre 10 et 120 ans)';
                    this.showError = true;
                    return;
                }

                // Validation spécifique pour le poids cible
                if (this.langKey === 'targetWeight') {
                    const responses = this.$parent.responses || {};
                    const actualWeight = parseFloat(responses.actualWeight);
                    const weightObjective = responses.weightObjective;
                    const heightCm = parseFloat(responses.actualSize);

                    // Vérifier la cohérence avec l'objectif
                    if (weightObjective === 'loseWeight' && numValue >= actualWeight) {
                        this.errorMessage = 'Votre poids cible doit être inférieur à votre poids actuel pour perdre du poids';
                        this.showError = true;
                        return;
                    }

                    if (weightObjective === 'gainWeight' && numValue <= actualWeight) {
                        this.errorMessage = 'Votre poids cible doit être supérieur à votre poids actuel pour prendre du poids';
                        this.showError = true;
                        return;
                    }

                    // Vérifier que l'IMC cible ne sera pas inférieur à 15
                    if (heightCm && heightCm > 0) {
                        const heightM = heightCm / 100;
                        const targetBMI = numValue / (heightM * heightM);
                        
                        if (targetBMI < 15) {
                            this.errorMessage = `Ce poids cible donnerait un IMC de ${targetBMI.toFixed(1)}, ce qui est trop bas (minimum 15)`;
                            this.showError = true;
                            return;
                        }
                    }

                    // Vérifier les limites réalistes
                    if (numValue < 20 || numValue > 300) {
                        this.errorMessage = 'Veuillez entrer un poids cible réaliste (entre 20 et 300 kg)';
                        this.showError = true;
                        return;
                    }
                }
            }

            // Émettre la mise à jour
            this.$emit('update', { key: this.langKey, value: this.valueLocal });

            // Vérifier l'IMC après avoir mis à jour le poids ou la taille
            if (this.langKey === 'actualWeight' || this.langKey === 'actualSize') {
                setTimeout(() => {
                    if (!this.checkBMI()) {
                        return;
                    }
                    this.proceedToNext();
                }, 100);
            } else {
                this.proceedToNext();
            }
            
            this.errorMessage = '';
            this.showError = false;
        },
        proceedToNext() {
            if (!this.multipleChoice && this.type !== 'text' && this.type !== 'number') {
                // Délai pour permettre l'animation visuelle
                setTimeout(() => {
                    this.$emit('nextStep');
                }, 200);
            } else {
                this.$emit('nextStep');
            }
        },
        selectOption(option) {
            if (this.type === 'checkbox') {
                if (!Array.isArray(this.valueLocal)) this.valueLocal = [];
                const index = this.valueLocal.indexOf(option);
                if (index > -1) {
                    this.valueLocal.splice(index, 1);
                } else {
                    this.valueLocal.push(option);
                }
            } else {
                this.valueLocal = option;
                if (!this.multipleChoice) this.submit();
            }
        },
        previousStep() {
            this.showBMIError = false;
            this.$emit('previousStep');
        },
    },
};
</script>

