<template>
  <div class="main bg-primary">
    <div class="flex_row_between w60">
        <v-progress-linear
          color="accent"
          height="10"
          :model-value="currentQuestionIndex + 1"
          :max="totalVisibleQuestions"
          striped
        ></v-progress-linear>
        <div>
          <p class="text-white ml-6 flex_row">
            {{ currentQuestionIndex + 1 }} / {{ totalVisibleQuestions }}
          </p>
        </div>
    </div>
    <div class="spacer"></div>
    <Register_question_block
      v-if="currentQuestion"
        :question="currentQuestion.question"
        :options="currentQuestion.options"
        :multipleChoice="currentQuestion.multipleChoice"
        :type="currentQuestion.type"
        :langKey="currentQuestion.key"
        :value="responses[currentQuestion.key]"
        @nextStep="nextStep"
        @previousStep="previousStep"
        @update="updateAnswer"
    />
  </div>
</template>
<script>
import { formStore } from '@/store/register_store';
import questions from '@/data/register_questions.json';
import Register_question_block from '../Utils/Account/register_question_block.vue';

export default {
  emits: ['nextStep', 'previousStep', 'update'],
  name: 'RegisterQuestions',
  components: { Register_question_block },
  data() {
    return {
      step: 0,
      questions,
      responses: formStore.responses,
      visibleQuestions: [],
    };
  },
  watch: {
    step(newStep) {
      this.cleanMultipleChoiceResponses(newStep);
    },
    responses: {
      handler() {
        this.updateVisibleQuestions();
      },
      deep: true,
    },
  },
  computed: {
    currentQuestion() {
      return this.visibleQuestions[this.step] || null;
    },
    currentQuestionIndex() {
      return this.step;
    },
    totalVisibleQuestions() {
      return this.visibleQuestions.length;
    },
  },
  methods: {
    shouldShowQuestion(question) {
      // Si la question n'a pas de condition, elle est toujours visible
      if (!question.conditional || !question.showIf) {
        return true;
      }

      const { key, values } = question.showIf;
      const responseValue = this.responses[key];

      // Vérifier si la valeur de la réponse correspond aux conditions
      if (Array.isArray(values)) {
        return values.includes(responseValue);
      }

      return responseValue === values;
    },
    updateVisibleQuestions() {
      this.visibleQuestions = this.questions.filter(q => this.shouldShowQuestion(q));
    },
    cleanMultipleChoiceResponses(currentStep) {
      const currentQ = this.visibleQuestions[currentStep];
      if (currentQ?.multipleChoice) {
        if (!this.responses[currentQ.key] || !Array.isArray(this.responses[currentQ.key])) {
          this.responses[currentQ.key] = [];
        }
      }
    },
    updateAnswer({ key, value }) {
      this.responses[key] = value;
    },
    nextStep() {
      if (this.step < this.visibleQuestions.length - 1) {
        this.step++;
      } else {
        const allAnswered = this.visibleQuestions.every(q => {
          const response = this.responses[q.key];
          return response !== undefined && response !== null && response !== '';
        });
        
        if (allAnswered) {
          this.$router.push('/final_register');
        } else {
          alert('Veuillez répondre à toutes les questions !');
        }
      }
    },
    previousStep() {
      if (this.step > 0) {
        this.step--;
      }
    },
  },
  mounted() {
    // Initialiser les questions visibles
    this.updateVisibleQuestions();

    // Initialiser les tableaux vides pour les questions à choix multiples
    this.visibleQuestions.forEach(q => {
      if (q.multipleChoice && !this.responses[q.key]) {
        this.responses[q.key] = [];
      }
    });
  },
};
</script>
<style scoped>
  .w60 {
      width: 60%;
  }
  .spacer {
      margin-top: 2em;
      margin-bottom: 2em;
  }
  .main {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: flex-start;
  }
</style>