<template>
  <loading-element v-if="authStore.isLoading" />
  <div class="main bg-primary" v-else>
    <div class="rowSpaceBetween fullWidth mb-5">
      <TopDeck
        v-if="authStore.userInfos"
        firstElement="Catalogue"
        secondElement="de recettes"
        :coloredSecond="true"
        actionHeaderIcon="mdi-arrow-left"
        :actionheaderFunction="() => $router.push('/my_recipes')"
        actionHeaderColor="accent"
        actionHeaderTextColor="white"
      />
      <div class="rowCustom">
        <ThemeToggle />
        <AccountToggle />
      </div>
    </div>

    <v-btn
      color="accent"
      rounded="lg"
      @click="router.push('/base_recipes_import')"
      class="white-text-button mb-3 mr-3"
    >
      <v-icon class="mr-1">mdi-plus</v-icon>
      <span>Importer des recettes de base</span>
    </v-btn>

    <v-btn
      color="accent"
      rounded="lg"
      @click="router.push('/base_recipes')"
      class="white-text-button mb-3"
    >
      <v-icon class="mr-1">mdi-plus</v-icon>
      <span>Ajouter une recette de base</span>
    </v-btn>

    <v-row no-gutters>
      <v-col cols="12" md="12" class="pr-2">
        <div class="pa-4 bg-secondary rounded-xl">
          <div class="d-flex align-center justify-space-between">
            <h1 class="text">Recettes mises en avant</h1>

          </div>

          <!-- Recherche + Filtre -->
          <div
            class="d-flex align-center my-4"
            style="gap: 1rem; flex-wrap: wrap"
          >
            <v-text-field
              v-model="searchQuery"
              placeholder="Rechercher (titre, catégorie, notes)"
              hide-details
              density="compact"
              variant="tonal"
              prepend-inner-icon="mdi-magnify"
              class="searchField rounded-lg flex-1-1 bg-tertiary"
              rounded="lg"
            />

            <v-select
              v-model="selectedCategory"
              :items="categories"
              label="Catégorie"
              hide-details
              density="compact"
              variant="tonal"
              class="categorySelector rounded-lg"
              style="min-width: 200px"
            />
          </div>

          <!-- Loader -->
          <div v-if="isLoadingRecipes" class="d-flex justify-center my-10">
            <v-progress-circular indeterminate color="primary" />
          </div>

          <!-- Vide -->
          <v-alert
            v-else-if="!filteredRecipes.length"
            type="info"
            variant="tonal"
            class="mt-4"
          >
            Aucune recette à afficher.
          </v-alert>

          <div
            v-for="(recipesByCat, catName) in groupedRecipes"
            :key="catName"
            class="mb-8"
          >
            <!-- Titre + bouton de pliage -->
            <div
              class="d-flex align-center justify-space-between mb-2 cursor-pointer"
              @click="toggleGroup(catName)"
            >
              <h2 class="recipeContainerTitle mb-0 text-white">
                {{ $t(catName) }}
              </h2>

              <v-btn icon variant="text" color="grey-darken-1" size="small">
                <v-icon>
                  {{
                    openGroups[catName] ? "mdi-chevron-up" : "mdi-chevron-down"
                  }}
                </v-icon>
              </v-btn>
            </div>

            <!-- Contenu pliable -->
            <v-expand-transition>
              <div v-show="openGroups[catName]" class="mt-2">
                <v-row dense>
                  <v-col
                    v-for="item in recipesByCat"
                    :key="item.id"
                    cols="12"
                    sm="6"
                    md="4"
                    lg="3"
                  >
                    <BaseRecipeCard
                      :item="item"
                      :disabled="addingIds.includes(item.id)"
                      @add="addToMyRecipes"
                      @view="openDetails"
                    />
                  </v-col>
                </v-row>
              </div>
            </v-expand-transition>
          </div>
        </div>
      </v-col>
    </v-row>

    <v-snackbar v-model="snack.show" :timeout="2500">
      {{ snack.text }}
    </v-snackbar>
    <v-snackbar v-if="errorMessage" color="error" timeout="3000" top right>
      {{ errorMessage }}
    </v-snackbar>
  </div>
</template>

<script>
import { ref, computed, onMounted, watch } from "vue";
import { useRouter } from "vue-router";
import LoadingElement from "@/components/Animations/LoadingElement.vue";
import TopDeck from "@/components/Utils/TopDeck.vue";
import { useAuthStore } from "@/store/auth_store";
import ThemeToggle from "@/components/Utils/ThemeToggle.vue";
import AccountToggle from "@/components/Utils/AccountToggle.vue";
import { getBaseRecipes  } from "@/service/recipe_manager";
import { addBaseRecipeToUser } from "@/service/food_manager";
import BaseRecipeCard from '@/components/Kitchen/Recipes/BaseRecipeCard.vue'

export default {
  name: "BaseRecipesCatalog",
  components: { LoadingElement, TopDeck, ThemeToggle, AccountToggle, BaseRecipeCard },
  setup() {
  const authStore = useAuthStore();
  const errorMessage = ref("");
  const snack = ref({ show: false, text: "" });
  const router = useRouter();

    const recipes = ref([]); // [{ id, title, category, notes, totals, servings, favorite }]
    const isLoadingRecipes = ref(false);
    const selectedRecipe = ref(null);
    const searchQuery = ref("");
    const selectedCategory = ref("Toutes");
  const openGroups = ref({});
  const addingIds = ref([]);

    const categories = computed(() => {
      const cats = new Set(
        recipes.value.map((r) => r.category).filter(Boolean)
      );
      return ["Toutes", ...cats];
    });

    const filteredRecipes = computed(() => {
      const q = searchQuery.value.trim().toLowerCase();
      const cat = selectedCategory.value;

      return recipes.value.filter((item) => {
        const title = (item.title || "").toLowerCase();
        const category = String(item.category || "").toLowerCase();
        const notes = (item.notes || "").toLowerCase();

        const matchSearch =
          !q || title.includes(q) || category.includes(q) || notes.includes(q);
        const matchCategory = cat === "Toutes" || item.category === cat;

        return matchSearch && matchCategory;
      });
    });

    const groupedRecipes = computed(() => {
      if (selectedCategory.value !== "Toutes") {
        return { [selectedCategory.value]: filteredRecipes.value };
      }

      const groups = {};
      filteredRecipes.value.forEach((item) => {
        const cat = item.category || "Sans catégorie";
        if (!groups[cat]) groups[cat] = [];
        groups[cat].push(item);
      });
      return groups;
    });

    function toggleGroup(catName) {
      openGroups.value[catName] = !openGroups.value[catName];
    }

    function select(item) {
      selectedRecipe.value = item;
      // Tu peux ouvrir un drawer ou une page détail si besoin
    }

    function openDetails(id) {
      // reuse existing recipe detail route
      router.push({ name: 'recipe_detail', params: { id } })
    }

    async function addToMyRecipes(item) {
      if (!authStore?.userid) {
        errorMessage.value = "Utilisateur non connecté.";
        return;
      }

      const key = item.id || item.baseId || item.title;
      if (addingIds.value.includes(key)) return;
      addingIds.value.push(key);

      try {
        const res = await addBaseRecipeToUser(authStore.userid, item, item.id);
        if (res && res.existed) {
          // already exists
          snack.value = { show: true, text: "Vous possédez déjà cette recette." };
        } else {
          snack.value = { show: true, text: "Recette ajoutée à vos recettes ✅" };
        }
      } catch (e) {
        console.error("Erreur ajout recette utilisateur:", e);
        errorMessage.value = "Erreur lors de l'ajout de la recette.";
      } finally {
        const idx = addingIds.value.indexOf(key);
        if (idx !== -1) addingIds.value.splice(idx, 1);
      }
    }

    onMounted(() => {
      watch(
        () => authStore.userInfos,
        async () => {
          if (!authStore?.userid) return;
          try {
            isLoadingRecipes.value = true;
            const data = await getBaseRecipes();
            // data = { recipeId: {title, ...}, ... }
            recipes.value = Object.entries(data).map(([id, value]) => ({
              id,
              ...value,
            }));
            const cats = [
              ...new Set(
                recipes.value.map((r) => r.category || "Sans catégorie")
              ),
            ];
            cats.forEach((cat) => {
              openGroups.value[cat] = true;
            });
          } catch (error) {
            console.error("Erreur récupération recettes:", error);
            errorMessage.value = "Erreur lors du chargement des recettes.";
          } finally {
            isLoadingRecipes.value = false;
          }
        },
        { immediate: true }
      );
    });

    return {
      authStore,
      errorMessage,
      snack,
      router,
      recipes,
      selectedRecipe,
      select,
      addToMyRecipes,
      openDetails,
      searchQuery,
      selectedCategory,
      categories,
      addingIds,
      openGroups,
      toggleGroup,
      filteredRecipes,
      groupedRecipes,
      isLoadingRecipes,
    };
  },
};
</script>

